/**
 * The Citadel App ABI, version 1, as the host reads it. Every name, number and code comes from
 * the generated SSOT (`citadel-app-sdk-types`, copied into ../sdk/generated by ts-rs and held to
 * the Rust by a drift test); this file only gives the host's modules one place to import from.
 *
 * Replies are handles: a host call answers a handle (>= 0) the guest reads with `reply_read`. A
 * refusal is still a reply ({refused: ...}); a negative code means the call itself was malformed
 * at the ABI level. A reply that is not ready yet reads as PENDING until the host delivers
 * AppEvent `{reply_ready: {handle}}`: the browser cannot block a worker on a port.
 */
import {
  ABI_ERROR, ABI_NAMESPACE, EXPORT_ALLOC, EXPORT_EVENT, EXPORT_FRAME, EXPORT_FREE, EXPORT_INIT, GROUPS, INIT_RESULT,
  MEMORY_IMPORT, OPTIONAL_EXPORTS, REPLY_LEN, REPLY_READ, REQUIRED_EXPORTS,
} from '../sdk/generated/AbiConstants';
import type { Group } from '../sdk/generated/Group';

export {
  ABI_ERROR, ABI_NAMESPACE, EXPORT_ALLOC, EXPORT_EVENT, EXPORT_FRAME, EXPORT_FREE, EXPORT_INIT, INIT_RESULT,
  MEMORY_IMPORT, OPTIONAL_EXPORTS, REPLY_LEN, REPLY_READ, REQUIRED_EXPORTS,
};

export type AbiGroup = Group;

/** The groups in index order (canvas 0 ... log 15). */
export const ABI_GROUPS: readonly AbiGroup[] = (Object.keys(GROUPS) as AbiGroup[]).sort((a: AbiGroup, b: AbiGroup) => GROUPS[a] - GROUPS[b]);

export function groupIndex(group: AbiGroup): number {
  return GROUPS[group];
}

export function isAbiGroup(name: string): name is AbiGroup {
  return Object.hasOwn(GROUPS, name);
}
